import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as t,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Doubao tutorial","description":"Open Doubao on the web or desktop and send the first message. Only official doors and copy.","frontmatter":{"title":"Doubao tutorial","description":"Open Doubao on the web or desktop and send the first message. Only official doors and copy.","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"products/doubao/doubao.md","filePath":"products/doubao/doubao.md","lastUpdated":1787107158000}'),n={name:"products/doubao/doubao.md"};function i(d,e,s,l,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="doubao-tutorial" tabindex="-1">Doubao tutorial <a class="header-anchor" href="#doubao-tutorial" aria-label="Permalink to &quot;Doubao tutorial&quot;">​</a></h1><blockquote><p>Start at <a href="https://www.doubao.com/" target="_blank" rel="noreferrer">doubao.com</a> or the <a href="https://www.doubao.com/download/desktop" target="_blank" rel="noreferrer">desktop landing</a>. This page only repeats doors you can check on official pages.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> a frontend engineer opening Doubao for the first time.</p><p><strong>You will:</strong> send a first message on web or desktop, and see what the desktop page adds.</p><p><strong>You will not:</strong> install Trae, call the Ark API, build a Coze agent, or invent prices.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You can open <code>doubao.com</code>. Some networks resolve it into <code>198.18.0.0/15</code>. Change DNS / disable Fake-IP before you decide the site is down.</li><li>Some regions ask you to sign in first, or suggest <strong>Dola</strong>. Dola is not this tutorial.</li></ul><h2 id="open-it-in-15-minutes" tabindex="-1">Open it in 15 minutes <a class="header-anchor" href="#open-it-in-15-minutes" aria-label="Permalink to &quot;Open it in 15 minutes&quot;">​</a></h2><h3 id="_1-pick-an-official-door" tabindex="-1">1. Pick an official door <a class="header-anchor" href="#_1-pick-an-official-door" aria-label="Permalink to &quot;1. Pick an official door&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>How</th><th>Source</th></tr></thead><tbody><tr><td>Web</td><td>Open <a href="https://www.doubao.com/" target="_blank" rel="noreferrer">doubao.com</a>, sign in, ask</td><td>Homepage</td></tr><tr><td>Web from desktop landing</td><td><a href="https://www.doubao.com/download/desktop" target="_blank" rel="noreferrer">download/desktop</a> → <strong>使用网页版</strong></td><td>Desktop page</td></tr><tr><td>Windows / macOS</td><td><a href="https://www.doubao.com/download/" target="_blank" rel="noreferrer">download</a> or <strong>下载豆包桌面版</strong></td><td>Official download</td></tr><tr><td>Microsoft Store</td><td>App id <code>XPDDTBMM6TZ365</code></td><td><a href="https://apps.microsoft.com/detail/xpddtbmm6tz365" target="_blank" rel="noreferrer">Store</a></td></tr><tr><td>Android</td><td>Yingyongbao package <code>com.larus.nova</code> (Beijing Chuntian Zhiyun Technology Co., Ltd.)</td><td><a href="https://sj.qq.com/appdetail/com.larus.nova" target="_blank" rel="noreferrer">Yingyongbao</a></td></tr></tbody></table><p>Minimum OS versions were <strong>not</strong> visible in the no-JS scrape on 2026-08-19. Use the installer page.</p><h3 id="_2-send-the-first-message" tabindex="-1">2. Send the first message <a class="header-anchor" href="#_2-send-the-first-message" aria-label="Permalink to &quot;2. Send the first message&quot;">​</a></h3><p>After login, type in the box. Official copy positions Doubao as chat, writing, copy, translation, and a coding helper. Treat it as a conversation assistant. Do not expect it to clone a repo or open a PR.</p><h3 id="_3-what-the-desktop-page-adds" tabindex="-1">3. What the desktop page adds <a class="header-anchor" href="#_3-what-the-desktop-page-adds" aria-label="Permalink to &quot;3. What the desktop page adds&quot;">​</a></h3><p>Install the desktop client only if you need local productivity. Official desktop copy:</p><ul><li>Writing, translation, one-click PPT, Excel</li><li>Seedream 5.0 image and Seedance 2.5 video (Pro)</li><li>A built-in planning Agent</li></ul><p>There is no official click-path tree. This page does not invent one.</p><h2 id="official-capabilities" tabindex="-1">Official capabilities <a class="header-anchor" href="#official-capabilities" aria-label="Permalink to &quot;Official capabilities&quot;">​</a></h2><h3 id="homepage-download-meta" tabindex="-1">Homepage / download meta <a class="header-anchor" href="#homepage-download-meta" aria-label="Permalink to &quot;Homepage / download meta&quot;">​</a></h3><p>Seedance <strong>2.0</strong> is on Doubao and free after login. Doubao is described as a chat assistant for writing, copy, translation, and coding help.</p><h3 id="desktop-landing" tabindex="-1">Desktop landing <a class="header-anchor" href="#desktop-landing" aria-label="Permalink to &quot;Desktop landing&quot;">​</a></h3><p><a href="https://www.doubao.com/download/desktop" target="_blank" rel="noreferrer">download/desktop</a> names <strong>Seedream 5.0</strong>, <strong>Seedance 2.5</strong>, and an <strong>Agent</strong>.</p><p><strong>The two official Seedance version strings disagree.</strong> This site quotes both.</p><h3 id="coding-boundary" tabindex="-1">Coding boundary <a class="header-anchor" href="#coding-boundary" aria-label="Permalink to &quot;Coding boundary&quot;">​</a></h3><p>Repo-level coding is <a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a> (#80). Calling Doubao models from your service is <a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">Volcengine Ark</a> (#82).</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./doubao-cheatsheet.html">Cheatsheet</a></li><li><a href="./doubao-glossary.html">Glossary</a></li><li><a href="/tech/fundamentals/LLM.html">Learn LLM</a></li></ul>',28)])])}const m=a(n,[["render",i]]);export{b as __pageData,m as default};
